using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;

static class PatchChecks {
 static T F<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static IEnumerable<T> All<T>(DependencyObject root) where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in All<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static Action<bool,string> Log(string path,List<string> lines){return (ok,text)=>{lines.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(path,lines.ToArray());if(!ok)throw new Exception(text);};}
 static void Isolate(string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);}
 public static void Core(string path){Isolate(path);var lines=new List<string>();var check=Log(path,lines);try{File.WriteAllText(Path.Combine(Engine.DataRoot,"settings-ver1.2.1.tsv"),"font\t22\nauto\t0\ntheme\tdark\n");AppSettings.Load();check(AppSettings.EditorFont==22&&AppSettings.InterfaceFont==13&&AppSettings.Night&&!AppSettings.AutoCheck,"Old settings retain code font, theme and update choice; UI size defaults to 13");foreach(int size in AppSettings.InterfaceFontSizes){AppSettings.SetInterfaceFont(size);check(AppSettings.InterfaceFont==size&&AppSettings.EditorFont==22,"UI font independently selected: "+size);}typeof(AppSettings).GetField("loaded",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,false);check(AppSettings.InterfaceFont==16&&AppSettings.EditorFont==22,"Both font preferences reload independently");Version v;check(UpdateService.TryVersion("ver1.2.1.2",out v)&&v==UpdateService.Current,"Embedded version is ver1.2.1.2");string own=Assembly.GetExecutingAssembly().Location;UpdateService.Verify(own,UpdateService.HashFile(own),new FileInfo(own).Length,v);check(true,"EXE size, checksum and four-part file version verification");check(!UpdateInstaller.NeedsElevation(Engine.DataRoot),"Writable application directory updates without administrator privileges");check(Directory.GetFiles(Engine.DataRoot,".Feng-write-*").Length==0,"Writeability check leaves no temporary files");var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();string raw=serializer.Serialize(new{tag_name="ver1.2.1.3",draft=false,prerelease=false,assets=new[]{new{name="Feng_C_Practice_ver1.2.1.3.exe",state="uploaded",size=4096,browser_download_url=UpdateService.Repo+"/releases/download/ver1.2.1.3/Feng_C_Practice_ver1.2.1.3.exe",digest="sha256:"+new string('a',64)}}});var next=UpdateService.Parse(raw);check(next.Newer&&next.CanInstall&&next.VersionText=="1.2.1.3","Future official four-part Release is available for in-app update");check(!UpdateService.Parse(raw.Replace("1.2.1.3","1.2.1.1")).CanInstall,"Published old Release cannot downgrade this local build");lines.Add("ALL PATCH CORE CHECKS PASSED");File.WriteAllLines(path,lines.ToArray());}catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(path,lines.ToArray());Environment.ExitCode=1;}}
 static Rect IconBounds(Button b){var icon=b.Content as FrameworkElement;return new Rect(icon.TranslatePoint(new Point(),b),new Size(icon.ActualWidth,icon.ActualHeight));}
 static async Task Close(Window w){w.Close();await Task.Delay(240);}
 public static void UI(Application app,string path){Isolate(path);AppSettings.Load();GlassTheme.Apply(false,false);var lines=new List<string>();var check=Log(path,lines);var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{await Transitions.WhenReady(main);main.PreviewSize(1600,1000);await Task.Delay(60);var editor=F<CodeEditor>(main,"editor");string code="#include <stdio.h>\nint main(void)\n{\n    int value = 12;\n    printf(\"%d\", value);\n    return 0;\n}\n";editor.Text=code;editor.Input.CaretOffset=code.IndexOf("int value");editor.Input.SelectedText=" ";string edited=editor.Text;var document=editor.Input.Document;int offset=editor.Input.CaretOffset;check(main.WindowStyle==WindowStyle.None,"Main keeps integrated top and custom frame");
 var settings=new SettingsWindow(false,true){Owner=main};settings.Show();await Transitions.WhenReady(settings);check(GlassChrome.UsesNativeFrame(settings)&&settings.Content is Grid&&((FrameworkElement)settings.Content).Clip==null,"Settings uses default system frame with no competing outer rounded clip");check(F<Button>(settings,"install").Content.ToString()=="一键更新并重启","One in-app update action describes automatic download and restart");foreach(int size in AppSettings.InterfaceFontSizes){F<List<Button>>(settings,"interfaceChoices").First(b=>(string)b.Tag=="ui-font:"+size).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(60);check(AppSettings.InterfaceFont==size&&editor.Input.FontSize==16&&editor.Text==edited&&editor.Input.Document==document&&editor.Input.CaretOffset==offset,"UI font "+size+" preserves code font, text, document and caret");check(Math.Abs(F<TextBlock>(main,"title").FontSize-20*size/13.0)<.01,"Main title font applies exactly once at "+size);check(settings.Width<=main.ActualWidth&&settings.Height<=main.ActualHeight,"Settings stays within owner at UI font "+size);}
 F<List<Button>>(settings,"fontChoices").First(b=>(int)b.Tag==24).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(editor.Input.FontSize==24&&AppSettings.InterfaceFont==16,"Code size remains independent of UI size");Theme.Capture((FrameworkElement)settings.Content,Path.Combine(Path.GetDirectoryName(path),"设置-界面16-代码24.png"),144);await Close(settings);
 var welcome=new WelcomeWindow{Owner=main};welcome.Show();await Transitions.WhenReady(welcome);check(GlassChrome.UsesNativeFrame(welcome),"Startup welcome uses default native frame");Theme.Capture((FrameworkElement)welcome.Content,Path.Combine(Path.GetDirectoryName(path),"欢迎说明-默认外框内容.png"),144);await Close(welcome);
 AppSettings.SetInterfaceFont(13);AppSettings.SetFont(16);var buttons=All<Button>(main).Where(b=>(b.Tag as string??"").StartsWith("icon:")).ToList();foreach(string command in new[]{"设置","知识点学习","提示 / 标准答案","评分说明"}){var b=buttons.First(x=>(string)x.Tag=="icon:"+command);var before=IconBounds(b);Thickness thickness=b.BorderThickness;for(int cycle=0;cycle<2;cycle++){Keyboard.Focus(b);main.UpdateLayout();check(IconBounds(b)==before&&b.BorderThickness==thickness,"Focused icon bounds stable: "+command+" / "+cycle);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};timer.Tick+=(a,c)=>{timer.Stop();var popup=main.OwnedWindows.Cast<Window>().FirstOrDefault(w=>w.IsVisible);if(popup==null)throw new Exception("No modal opened for "+command);check(GlassChrome.UsesNativeFrame(popup),"Modal uses system frame: "+command);popup.Close();};timer.Start();b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));main.UpdateLayout();check(IconBounds(b)==before&&b.BorderThickness==thickness,"Icon unchanged after modal closes: "+command+" / "+cycle);}}
 var game=new ChallengeWindow(true){Owner=main};game.Show();await Transitions.WhenReady(game);check(GlassChrome.UsesNativeFrame(game),"Challenge secondary window also uses the native frame");game.Editor.Text=code;editor.Text=code;int hits=0;foreach(int ui in new[]{12,13,16}){AppSettings.SetInterfaceFont(ui);foreach(bool dark in new[]{false,true}){AppSettings.SetNight(dark);await Task.Delay(320);foreach(double dpi in new[]{96.0,144.0,192.0}){double width=2560*96/dpi,height=1600*96/dpi;main.PreviewSize(width,height);game.PreviewSize(width,height);foreach(int size in AppSettings.FontSizes){AppSettings.SetFont(size);main.UpdateLayout();game.UpdateLayout();await Task.Delay(15);foreach(var ed in new[]{editor,game.Editor}){ed.Input.ScrollToHome();ed.RefreshView();for(int i=0;i<code.Length-1;i++){if(code[i]=='\n'||code[i+1]=='\n')continue;var a=ed.Input.CharacterRect(i);var b=ed.Input.CharacterRect(i+1);if(b.X<=a.X)continue;if(ed.Input.Hit(new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5))!=i)throw new Exception("Cursor mismatch "+ui+" / "+dark+" / "+dpi+" / "+size);hits++;}}}check(editor.ActualHeight>=120&&game.Editor.ActualHeight>=120,"Readable independent editors at UI "+ui+" dark "+dark+" layout "+dpi+"dpi; heights "+editor.ActualHeight.ToString("0")+" / "+game.Editor.ActualHeight.ToString("0"));}}}
 check(hits>17000,"All character hit positions match: "+hits);AppSettings.SetInterfaceFont(16);AppSettings.SetFont(24);main.PreviewSize(1280,800);game.PreviewSize(1280,800);await Task.Delay(100);Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"主界面-界面16-代码24-200dpi布局.png"),192);Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"暗域-界面16-代码24-200dpi布局.png"),192);await Close(game);AppSettings.SetNight(false);AppSettings.SetInterfaceFont(13);AppSettings.SetFont(16);main.PreviewSize(1600,1000);Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"主界面-ver1.2.1.2.png"),153.6);lines.Add("ALL PATCH UI CHECKS PASSED");File.WriteAllLines(path,lines.ToArray());main.Close();
 }catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(path,lines.ToArray());app.Shutdown(1);}};app.Run(main);}
}
